class LinearSearchService<T extends Comparable<? super T>> implements SearchAlgorithm<T> {
    @Override
    public SearchResult search(SearchRequest<T> request) {
        if (request == null) {
            throw new IllegalArgumentException("request must not be null");
        }

        T[] values = request.values();
        T target = request.target();

        for (int index = 0; index < values.length; index++) {
            T value = values[index];
            if (value == null) {
                throw new IllegalArgumentException("values must not contain null elements");
            }

            if (value.compareTo(target) == 0) {
                return SearchResult.found(index);
            }
        }

        return SearchResult.notFound();
    }
}

class BinarySearchService<T extends Comparable<? super T>> implements SearchAlgorithm<T> {
    @Override
    public SearchResult search(SearchRequest<T> request) {
        if (request == null) {
            throw new IllegalArgumentException("request must not be null");
        }

        T[] sortedValues = request.values();
        T target = request.target();

        int low = 0;
        int high = sortedValues.length - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            T midValue = sortedValues[mid];

            if (midValue == null) {
                throw new IllegalArgumentException("sortedValues must not contain null elements");
            }

            int comparison = midValue.compareTo(target);
            if (comparison == 0) {
                return SearchResult.found(mid);
            }

            if (comparison < 0) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return SearchResult.notFound();
    }
}

final class SearchAlgorithmFactory {
    private SearchAlgorithmFactory() {
    }

    static <T extends Comparable<? super T>> SearchAlgorithm<T> create(SearchType searchType) {
        return create(searchType, false);
    }

    static <T extends Comparable<? super T>> SearchAlgorithm<T> create(SearchType searchType, boolean loggingEnabled) {
        SearchAlgorithm<T> algorithm = createBase(searchType);
        if (loggingEnabled) {
            return new LoggingSearchAlgorithm<>(algorithm);
        }

        return algorithm;
    }

    private static <T extends Comparable<? super T>> SearchAlgorithm<T> createBase(SearchType searchType) {
        if (searchType == null) {
            throw new IllegalArgumentException("searchType must not be null");
        }

        switch (searchType) {
            case BINARY:
                return new BinarySearchService<>();
            case LINEAR:
                return new LinearSearchService<>();
            default:
                throw new IllegalArgumentException("Unsupported search type: " + searchType);
        }
    }

    static <T extends Comparable<? super T>> SearchAlgorithm<T> binarySearch() {
        return create(SearchType.BINARY);
    }
}

import java.util.logging.Logger;

class LoggingSearchAlgorithm<T extends Comparable<? super T>> implements SearchAlgorithm<T> {
    private static final Logger LOGGER = Logger.getLogger(LoggingSearchAlgorithm.class.getName());

    private final SearchAlgorithm<T> delegate;

    LoggingSearchAlgorithm(SearchAlgorithm<T> delegate) {
        if (delegate == null) {
            throw new IllegalArgumentException("delegate must not be null");
        }

        this.delegate = delegate;
    }

    @Override
    public SearchResult search(SearchRequest<T> request) {
        long startNanos = System.nanoTime();
        try {
            SearchResult result = delegate.search(request);
            logSuccess(result, System.nanoTime() - startNanos);
            return result;
        } catch (RuntimeException exception) {
            logFailure(exception, System.nanoTime() - startNanos);
            throw exception;
        }
    }

    private void logSuccess(SearchResult result, long elapsedNanos) {
        LOGGER.info("Search completed using " + delegateName()
                + " in " + elapsedNanos + " ns"
                + ", found=" + result.isFound()
                + ", index=" + result.index());
    }

    private void logFailure(RuntimeException exception, long elapsedNanos) {
        LOGGER.warning("Search failed using " + delegateName()
                + " in " + elapsedNanos + " ns"
                + ": " + exception.getMessage());
    }

    private String delegateName() {
        return delegate.getClass().getSimpleName();
    }
}

